mbr.copysrc:
     /* =================================================================== */
     /*                                                                     */
     /*  Documentation:                                                     */
     /*                                                                     */
     /*  Utility . . . : DLTOLDJRNR                                         */
     /*  Object  . . . : A_INSTALL  (PGM)                                   */
     /*  Source member : A_INSTALL                                          */
     /*  Source type . : CLLE                                               */
     /*  Description   : DLTOLDJRNR - Installer                             */
     /*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
     /*  Created . . . :                                                    */
     /*                                                                     */
     /* =================================================================== */
     /*                                                                     */
     /*  This software is free software, you can redistribute it and/or     */
     /*  modify it under the terms of the GNU General Public License (GPL)  */
     /*  as published by the Free Software Foundation.                      */
     /*                                                                     */
     /*  See GNU General Public License for details.                        */
     /*          http://www.opensource.org                                  */
     /*          http://www.opensource.org/licenses/gpl-license.html        */
     /*                                                                     */
     /* =================================================================== */
     /*  History:                                                           */
     /*                                                                     */
     /*  Datum       Name          Änderung                                 */
     /*  ----------  ------------  ---------------------------------------  */
     /*                                                                     */
     /* =================================================================== */
     /*   >>PRE-COMPILER<<                                                  */
     /*     >>CRTCMD<<    CRTBNDCL  PGM(QTEMP/&OB) +                        */
     /*                             SRCFILE(&SL/&SF) SRCMBR(&SM);           */
     /*     >>IMPORTANT<<                                                   */
     /*       >>PARM<<    OPTION(*EVENTF);                                  */
     /*     >>END-IMPORTANT<<                                               */
     /*     >>EXECUTE<<                                                     */
     /*     >>CMD<<       CALL   PGM(QTEMP/A_INSTALL) +                     */
     /*                   PARM('*CURRENT' '&SF' '&LI' 'GER');               */
     /*     >>CMD<<       DLTPGM PGM(QTEMP/A_INSTALL);                      */
     /*   >>END-PRE-COMPILER<<                                              */
     /* =================================================================== */
             PGM        PARM(&TGTRLS &SRCFILE &TOLIB &LNG)

             DCL        VAR(&TGTRLS   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&SRCFILE  ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&TOLIB    ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&LNG      ) TYPE(*CHAR) LEN( 3)

             DCL        VAR(&SRCLIB   ) TYPE(*CHAR) LEN(10)

             DCL        VAR(&CRTMSGF  ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&MSGF     ) TYPE(*CHAR) LEN(10) VALUE('DLTOLDJRNR')
             DCL        VAR(&PNLGRP   ) TYPE(*CHAR) LEN(10)
             DCL        VAR(&CMD      ) TYPE(*CHAR) LEN(10)

             CHGVAR     VAR(&SRCLIB) VALUE(&TOLIB   )

     /* -------------------------------- */
     /*  Delete old objects (prv. vers.) */
     /* -------------------------------- */
             DLTPGM     PGM(&TOLIB/DLTOLDJRR1)
             MONMSG     MSGID(CPF2105)

             DLTPNLGRP  PNLGRP(&TOLIB/DLTOLDJRPE)
             MONMSG     MSGID(CPF2105)

     /* -------------------------------- */
     /*  Delete old objects              */
     /* -------------------------------- */
             DLTCMD     CMD(&TOLIB/DLTOLDJRNR)
             MONMSG     MSGID(CPF2105)

             DLTPNLGRP  PNLGRP(&TOLIB/DLTOLDJRP)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DLTOLDJRR1)
             MONMSG     MSGID(CPF2105)

             DLTMOD     MODULE(&TOLIB/DLTOLDJRR2)
             MONMSG     MSGID(CPF2105)

             DLTPGM     PGM(&TOLIB/DLTOLDJRNR)
             MONMSG     MSGID(CPF2105)

             DLTMSGF    MSGF(&TOLIB/&MSGF)
             MONMSG     MSGID(CPF2105)

             RMVMSG     PGMQ(*SAME (*)) CLEAR(*ALL)

     /* -------------------------------- */
     /*  Create message file             */
     /* -------------------------------- */
             IF         COND(&LNG *EQ 'ENG') THEN(DO)
                CHGVAR     VAR(&CRTMSGF) VALUE('A_MSG_ENG')
                CHGVAR     VAR(&PNLGRP ) VALUE('DLTOLDJRPE')
                CHGVAR     VAR(&CMD    ) VALUE('DLTOLDJRNE')
             ENDDO
             ELSE       CMD(DO)
                CHGVAR     VAR(&CRTMSGF) VALUE('A_MSG_GER')
                CHGVAR     VAR(&PNLGRP ) VALUE('DLTOLDJRPG')
                CHGVAR     VAR(&CMD    ) VALUE('DLTOLDJRNG')
             ENDDO

             CRTMSGF    MSGF(&TOLIB/&MSGF) +
                          TEXT('Delete Old Journal Receivers              ')

             CRTCLPGM   PGM(QTEMP/&CRTMSGF) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*PGM) +
                          OPTION(*LSTDBG) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(&CRTMSGF  ) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CALL       PGM(QTEMP/&CRTMSGF) PARM(&TOLIB)
             DLTPGM     PGM(QTEMP/&CRTMSGF)

     /* -------------------------------- */
     /*  Create objects                  */
     /* -------------------------------- */
             CRTRPGMOD  MODULE(&TOLIB/DLTOLDJRR1) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DLTOLDJRR1) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTRPGMOD  MODULE(&TOLIB/DLTOLDJRR2) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(*MODULE) +
                          DBGVIEW(*LIST) TRUNCNBR(*NO) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DLTOLDJRR2) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTPGM     PGM(&TOLIB/DLTOLDJRNR) +
                          MODULE(&TOLIB/DLTOLDJRR1 +
                                 &TOLIB/DLTOLDJRR2) TEXT(*ENTMODTXT) +
                          ENTMOD(&TOLIB/DLTOLDJRR1) ACTGRP(*NEW) +
                          DETAIL(*BASIC) USRPRF(*USER) +
                          TGTRLS(&TGTRLS)
             DLTSPLF    FILE(DLTOLDJRNR) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTPNLGRP  PNLGRP(&TOLIB/DLTOLDJRP) SRCFILE(&SRCLIB/&SRCFILE) +
                          SRCMBR(&PNLGRP)
             DLTSPLF    FILE(DLTOLDJRP) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

             CRTCMD     CMD(&TOLIB/DLTOLDJRNR) PGM(&TOLIB/DLTOLDJRNR) +
                          SRCFILE(&SRCLIB/&SRCFILE) SRCMBR(&CMD) +
                          HLPPNLGRP(&TOLIB/DLTOLDJRP) HLPID(DLTOLDJRNR)
             DLTSPLF    FILE(&CMD) JOB(*) SPLNBR(*LAST)
             MONMSG     MSGID(CPF0000)

     /* -------------------------------- */
     /*  Delete obsolete objects         */
     /* -------------------------------- */
             DLTMOD     MODULE(&TOLIB/DLTOLDJRR1)
             DLTMOD     MODULE(&TOLIB/DLTOLDJRR2)

             ENDPGM

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0001                    */
     /* Program ended with errors. See job log.                     */
     /*-------------------------------------------------------------*/

             PGM        PARM(&TOLIB)

             DCL        VAR(&TOLIB) TYPE(*CHAR) LEN(10)

             RMVMSGD MSGID(USR0001) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0001) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'Program ended with errors. See job log.'                             +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0002                    */
     /* Deleted journal receiver: &2/&1.                            */
     /*-------------------------------------------------------------*/

             RMVMSGD MSGID(USR0002) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0002) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'Deleted journal receiver: &2/&1.'                                    +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 010) +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0003                    */
     /* &1 of &2 journal receiver deleted.                          */
     /*-------------------------------------------------------------*/

             RMVMSGD MSGID(USR0003) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0003) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'&1 of &2 journal receiver deleted.'                                  +
                ) +
                SEV(00) +
                FMT( +
                    (*DEC 010 0) +
                    (*DEC 010 0) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

             RCLRSC LVL(*)

             ENDPGM

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0001                    */
     /* Programm fehlerhaft beendet. Siehe Joblog.                  */
     /*-------------------------------------------------------------*/

             PGM        PARM(&TOLIB)

             DCL        VAR(&TOLIB) TYPE(*CHAR) LEN(10)

             RMVMSGD MSGID(USR0001) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0001) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'Programm fehlerhaft beendet. Siehe Joblog.'                          +
                ) +
                SEV(00) +
     /*   Keine Ersatzvariablen definiert!                          */ +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0002                    */
     /* Gelöschter Journalempfänger: &2/&1.                         */
     /*-------------------------------------------------------------*/

             RMVMSGD MSGID(USR0002) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0002) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'Gelöschter Journalempfänger: &2/&1.'                                 +
                ) +
                SEV(00) +
                FMT( +
                    (*CHAR 010) +
                    (*CHAR 010) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

     /*-------------------------------------------------------------*/
     /*   Cmd-ADDMSGD für Message-ID :   USR0003                    */
     /* Anzahl gelöschter Journalempfänger &1 von &2.               */
     /*-------------------------------------------------------------*/

             RMVMSGD MSGID(USR0003) MSGF(&TOLIB/DLTOLDJRNR)
             MONMSG  MSGID(CPF2419)     /* MsgID nicht gefunden */

             ADDMSGD +
                MSGID(USR0003) +
                MSGF(&TOLIB/DLTOLDJRNR) +
                MSG(+
'Anzahl gelöschter Journalempfänger &1 von &2.'                       +
                ) +
                SEV(00) +
                FMT( +
                    (*DEC 010 0) +
                    (*DEC 010 0) +
                ) +
                ALROPT(*NO) +
                CCSID( 65535) +
                /*  -EOF-  */

             RCLRSC LVL(*)

             ENDPGM

/* =================================================================== */
/*                                                                     */
/*  Kurzdokumentation :                                                */
/*                                                                     */
/*  Bereich . . . : DLTOLDJRNR                                         */
/*  Objekt  . . . : DLTOLDJRNR                                         */
/*  Beschreibung  : Tool: DLTOLDJRNR (Delete old Journal Rcv    )      */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*  Datum . . . . : 25.07.2001                                         */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/* >>PRE-COMPILER<<                                                    */
/*                                                                     */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/DLTOLDJRNR) +                     */
/*                           SRCFILE(&SL/&SF) +                        */
/*                           SRCMBR(&SM);                              */
/*                                                                     */
/*   >>COMPILE<<                                                       */
/*     >>PARM<< PGM(*LIBL/DLTOLDJRR1);                                 */
/*     >>PARM<< HLPPNLGRP(*LIBL/DLTOLDJRP );                           */
/*     >>PARM<< HLPID(DLTOLDJRNR);                                     */
/*     >>PARM<< PRDLIB(&LI);                                           */
/*   >>END-COMPILE<<                                                   */
/*                                                                     */
/*   >>EXECUTE<<                                                       */
/*                                                                     */
/* >>END-PRE-COMPILER<<                                                */
/* =================================================================== */

            CMD PROMPT('Alte Journalempfänger löschen')

      /* ------------------------------------------------------------ */
      /* Parameters for journal information                           */
      /* (QjoRetrieveJournalInformation)                              */
      /* ------------------------------------------------------------ */

            PARM KWD(JRN)        +
                 TYPE(QUAL1)     +
                 MIN(1)          +
                 PROMPT('Journal' 1)

      /* ------------------------------------------------------------ */
      /* Parameters for selection of receiver                         */
      /* ------------------------------------------------------------ */

            PARM KWD(AGE)        +
                 TYPE(*DEC)      +
                 LEN(3 0)        +
                 MIN(1)          +
                 PROMPT('Alter in Tagen' 5)

      /* ------------------------------------------------------------ */
      /* Processing parameters                                        */
      /* ------------------------------------------------------------ */
            PARM KWD(DETACH) +
                 TYPE(*CHAR) +
                 LEN(10) +
                 RSTD(*YES) +
                 DFT(*NO) +
                 SPCVAL( +
                        (*NO  )  +
                        (*YES )) +
                 MIN(0) +
                 PROMPT('Akt. Journalempfänger abhängen' 2)

            PARM KWD(SAVOPT) +
                 TYPE(*CHAR) +
                 LEN(10) +
                 RSTD(*YES) +
                 DFT(*SAVEDONLY) +
                 SPCVAL( +
                        (*SAVEDONLY  )  +
                        (*ALL        )) +
                 MIN(0) +
                 PROMPT('Sicherungsoption' 3)

      /* ------------------------------------------------------------ */
      /* Parameters for DLTJRNRCV command                             */
      /* ------------------------------------------------------------ */
            PARM KWD(DLTOPT) +
                 TYPE(*CHAR) +
                 LEN(11) +
                 RSTD(*YES) +
                 DFT(*NONE) +
                 SPCVAL( +
                        (*IGNINQMSG  )  +
                        (*IGNEXITPGM )  +
                        (*IGNTGTRCV  )) +
                 SNGVAL((*NONE )) +
                 MIN(0) +
                 MAX(3) +
                 PROMPT('Option' 4)

      /* ------------------------------------------------------------ */
      /* Parameters for log output                                    */
      /* ------------------------------------------------------------ */
            PARM KWD(LOGLVL) +
                 TYPE(*INT2) +
                 RSTD(*YES) +
                 DFT(*NONE) +
                 SPCVAL( +
                        (*NONE     0 )  +
                        (*BASIC    1 )  +
                        (*VERBOSE  2 )) +
                 MIN(0) +
                 PMTCTL(*PMTRQS) +
                 PROMPT('Log level' 6)

      /* ------------------------------------------------------------ */

   QUAL1:   QUAL TYPE(*NAME) LEN(10)
            QUAL TYPE(*NAME) LEN(10) SPCVAL(*LIBL *CURLIB)               +
                 DFT(*LIBL) +
                 PROMPT('Bibliothek')

/* =================================================================== */
/*                                                                     */
/*  Kurzdokumentation :                                                */
/*                                                                     */
/*  Bereich . . . : DLTOLDJRNR                                         */
/*  Objekt  . . . : DLTOLDJRNR                                         */
/*  Beschreibung  : Tool: DLTOLDJRNR (Delete old Journal Rcv    )      */
/*  Author  . . . : Thomas Raddatz   <thomas.raddatz@tools400.de>      */
/*  Datum . . . . : 25.07.2001                                         */
/*                                                                     */
/* =================================================================== */
/*                                                                     */
/*  This software is free software, you can redistribute it and/or     */
/*  modify it under the terms of the GNU General Public License (GPL)  */
/*  as published by the Free Software Foundation.                      */
/*                                                                     */
/*  See GNU General Public License for details.                        */
/*          http://www.opensource.org                                  */
/*          http://www.opensource.org/licenses/gpl-license.html        */
/*                                                                     */
/* =================================================================== */
/*  History:                                                           */
/*                                                                     */
/*  Datum       Name          Änderung                                 */
/*  ----------  ------------  ---------------------------------------  */
/*                                                                     */
/* =================================================================== */
/* >>PRE-COMPILER<<                                                    */
/*                                                                     */
/*   >>CRTCMD<< CRTCMD       CMD(&LI/DLTOLDJRNR) +                     */
/*                           SRCFILE(&SL/&SF) +                        */
/*                           SRCMBR(&SM);                              */
/*                                                                     */
/*   >>COMPILE<<                                                       */
/*     >>PARM<< PGM(*LIBL/DLTOLDJRR1);                                 */
/*     >>PARM<< HLPPNLGRP(*LIBL/DLTOLDJRP );                           */
/*     >>PARM<< HLPID(DLTOLDJRNR);                                     */
/*     >>PARM<< PRDLIB(&LI);                                           */
/*   >>END-COMPILE<<                                                   */
/*                                                                     */
/*   >>EXECUTE<<                                                       */
/*                                                                     */
/* >>END-PRE-COMPILER<<                                                */
/* =================================================================== */

            CMD PROMPT('Delete old Journal Receiver')

      /* ------------------------------------------------------------ */
      /* Parameters for journal information                           */
      /* (QjoRetrieveJournalInformation)                              */
      /* ------------------------------------------------------------ */

            PARM KWD(JRN)        +
                 TYPE(QUAL1)     +
                 MIN(1)          +
                 PROMPT('Journal' 1)

      /* ------------------------------------------------------------ */
      /* Parameters for selection of receiver                         */
      /* ------------------------------------------------------------ */

            PARM KWD(AGE)        +
                 TYPE(*DEC)      +
                 LEN(3 0)        +
                 MIN(1)          +
                 PROMPT('Age (days)' 5)

      /* ------------------------------------------------------------ */
      /* Processing parameters                                        */
      /* ------------------------------------------------------------ */
            PARM KWD(DETACH) +
                 TYPE(*CHAR) +
                 LEN(10) +
                 RSTD(*YES) +
                 DFT(*NO) +
                 SPCVAL( +
                        (*NO  )  +
                        (*YES )) +
                 MIN(0) +
                 PROMPT('Detach curr. journal reveicer' 2)

            PARM KWD(SAVOPT) +
                 TYPE(*CHAR) +
                 LEN(10) +
                 RSTD(*YES) +
                 DFT(*SAVEDONLY) +
                 SPCVAL( +
                        (*SAVEDONLY  )  +
                        (*ALL        )) +
                 MIN(0) +
                 PROMPT('Save option' 3)

      /* ------------------------------------------------------------ */
      /* Parameters for DLTJRNRCV command                             */
      /* ------------------------------------------------------------ */
            PARM KWD(DLTOPT) +
                 TYPE(*CHAR) +
                 LEN(11) +
                 RSTD(*YES) +
                 DFT(*NONE) +
                 SPCVAL( +
                        (*IGNINQMSG  )  +
                        (*IGNEXITPGM )  +
                        (*IGNTGTRCV  )) +
                 SNGVAL((*NONE )) +
                 MIN(0) +
                 MAX(3) +
                 PROMPT('Option' 4)

      /* ------------------------------------------------------------ */
      /* Parameters for log output                                    */
      /* ------------------------------------------------------------ */
            PARM KWD(LOGLVL) +
                 TYPE(*INT2) +
                 RSTD(*YES) +
                 DFT(*NONE) +
                 SPCVAL( +
                        (*NONE     0 )  +
                        (*BASIC    1 )  +
                        (*VERBOSE  2 )) +
                 MIN(0) +
                 PMTCTL(*PMTRQS) +
                 PROMPT('Log level' 6)

      /* ------------------------------------------------------------ */

   QUAL1:   QUAL TYPE(*NAME) LEN(10)
            QUAL TYPE(*NAME) LEN(10) SPCVAL(*LIBL *CURLIB)               +
                 DFT(*LIBL) +
                 PROMPT('Library')

/IF NOT DEFINED(PROTOTYPE) *=====================================================================* * * * Kurzdokumentation : * * * * Bereich . . . : DLTOLDJRNR * * Objekt . . . : DLTOLDJRR2 * * Beschreibung : Tool: DLTOLDJRNR (Delete old Journal Rcv ) Log * * Author . . . : Thomas Raddatz <thomas.raddatz@tools400.de> * * Datum . . . . : 08.01.2011 * * * *=====================================================================* * * * This software is free software, you can redistribute it and/or * * modify it under the terms of the GNU General Public License (GPL) * * as published by the Free Software Foundation. * * * * See GNU General Public License for details. * * http://www.opensource.org * * http://www.opensource.org/licenses/gpl-license.html * * * *=====================================================================* * History: * * * * Datum Name Änderung * * ---------- ------------ --------------------------------------- * * * *=====================================================================* * >>PRE-COMPILER<< * * >>CRTCMD<< CRTRPGMOD MODULE(&LI/&OB) + * * SRCFILE(&SL/&SF) SRCMBR(&SM); * * >>IMPORTANT<< * * >>PARM<< TRUNCNBR(*NO); * * >>PARM<< DBGVIEW(*LIST); * * >>END-IMPORTANT<< * * >>EXECUTE<< * * >>END-PRE-COMPILER<< * *=====================================================================* H NOMAIN /COPY QDLTOLDJRN,H_SPEC /COPY QDLTOLDJRN,COPYRIGHT * FQPRINT O F 132 PRINTER oflind(*in70) usropn D g_printData S 115A * /ENDIF * *************************************************************** * Exported Prototypes * *************************************************************** * D cLOGGER_NONE C 0 D cLOGGER_BASIC C 1 D cLOGGER_VERBOSE... D C 2 * * Opens the printer file for logging. D Logger_open... D PR D extproc('Logger_open') D i_logLvl 10I 0 value * * Appends a basic message to the printer file. D Logger_basic... D PR D extproc('Logger_basic') D i_message 110A const varying D options(*varsize: *nopass) * * Appends a verbose message to the printer file. D Logger_verbose... D PR D extproc('Logger_verbose') D i_message 110A const varying D options(*varsize: *nopass) * * Closes the printer file. D Logger_close... D PR D extproc('Logger_close') * /IF DEFINED(PROTOTYPE) /EOF /ENDIF * * *************************************************************** * External Prototypes * *************************************************************** * * ... Execute Command (QCMDEXC) API D QCMDEXC... D PR extpgm('QCMDEXC') D i_cmd 32702A const options(*varsize) D i_length 15P 5 const D i_IGCprcCtrl 3A const options(*nopass) * D QCMDEXC_IGC C 'IGC' * * *************************************************************** * Internal Prototypes * *************************************************************** * * Prints a message. D printMessage... D PR D extproc('printMessage') D i_message 110A const varying D options(*varsize: *nopass) * * *************************************************************** * Logger status * *************************************************************** * D g_logger... D DS qualified D logLvl 10I 0 inz * * *************************************************************** * O-Spec to print the sample data * *************************************************************** OQPRINT e PrintLine O g_printData 125 * OQPRINT e NewPage 6 O g_printData 125 * * *************************************************************** * Opens the printer file for logging. * *************************************************************** P Logger_open... P B export * D Logger_open... D PI D i_logLvl 10I 0 value * D CMD_OVRPRTF C 'OVRPRTF FILE(QPRINT) + D OVRFLW(60) HOLD(*YES) + D USRDTA('''') + D SPLFNAME(DLTOLDJRNR) + D OVRSCOPE(*CALLLVL)' * ------------------------------------------------------------- * /FREE
if (i_logLvl <= cLOGGER_NONE); return; endif;
if (not %open(QPRINT)); qcmdexc(CMD_OVRPRTF: %len(CMD_OVRPRTF)); open QPRINT; *in70 = *on; endif;
g_logger.logLvl = i_logLvl;
return;
/END-FREE * P Logger_open... P E * * *************************************************************** * Appends a "basic" message to the printer file. * *************************************************************** P Logger_basic... P B export * D Logger_basic... D PI D i_message 110A const varying D options(*varsize: *nopass) * ------------------------------------------------------------- * /FREE
if (g_logger.logLvl < cLOGGER_BASIC); return; endif;
if (%parms() >= 1); printMessage(i_message); else; printMessage(); endif;
return;
/END-FREE * P Logger_basic... P E * * *************************************************************** * Appends a "verbose" message to the printer file. * *************************************************************** P Logger_verbose... P B export * D Logger_verbose... D PI D i_message 110A const varying D options(*varsize: *nopass) * ------------------------------------------------------------- * /FREE
if (g_logger.logLvl < cLOGGER_VERBOSE); return; endif;
if (%parms() >= 1); printMessage(i_message); else; printMessage(); endif;
return;
/END-FREE * P Logger_verbose... P E * * *************************************************************** * Closes the printer file. * *************************************************************** P Logger_close... P B export * D Logger_close... D PI * ------------------------------------------------------------- * /FREE
if (%open(QPRINT)); close QPRINT; endif;
clear g_logger;
return;
/END-FREE * P Logger_close... P E * * *************************************************************** * Prints a message. * *************************************************************** P printMessage... P B * D printMessage... D PI D i_message 110A const varying D options(*varsize: *nopass) * ------------------------------------------------------------- * /FREE
if (*in70 = *on); except NewPage; *in70 = *off; endif;
if (%parms() >= 1); g_printData = i_message; else; g_printData = ''; endif;
except PrintLine;
g_printData = '';
return;
/END-FREE * P printMessage... P E *
